/*
 * pages/coordinator/ParticipantsPage.jsx - Participant list and registration.
 * GET /api/participants (only the logged-in coordinator's own), POST /api/participants. US-07, US-08.
 *
 * - The participant code (P-0001, ...) is generated by the backend; there is no code field.
 * - The logged-in coordinator becomes the owner automatically; the form only picks a reviewer.
 * - No names, dates of birth or contact details are ever collected.
 * - There is deliberately no delete button: participants are only ever set to WITHDRAWN.
 */
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { ChevronRight, Plus, ShieldCheck } from 'lucide-react';
import { api } from '@/api/client';
import { useAuth } from '@/components/common/AuthContext';
import {
  Badge, DataTable, ErrorBanner, Field, LoadState, Modal, PageHeading, SaveButton, StudySelect, dateOnly, useApi, useSave,
} from '@/components/common/ui';

const EMPTY = { study_id: '', reviewer_code: '', consent_status: 'ACTIVE' };

export default function ParticipantsPage() {
  const { user } = useAuth();
  const [studyFilter, setStudyFilter] = useState('');
  const participants = useApi(['participants', studyFilter], () => api.participants({ study_id: studyFilter }));
  const studies = useApi(['studies'], api.studies);
  const reviewers = useApi(['reviewers'], api.reviewers);
  const save = useSave();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState(EMPTY);
  const [created, setCreated] = useState('');

  const set = (key, value) => setForm(f => ({ ...f, [key]: value }));
  const activeStudies = studies.data?.filter(s => s.active) || [];

  function openForm() {
    setForm({ ...EMPTY, study_id: studyFilter });
    save.setError(null);
    setOpen(true);
  }

  async function submit(event) {
    event.preventDefault();
    // Only these three fields are sent; the backend sets the code and the owner.
    const participant = await save.run(() => api.registerParticipant({
      study_id: Number(form.study_id),
      reviewer_code: form.reviewer_code,
      consent_status: form.consent_status,
    }));
    if (participant) {
      setOpen(false);
      setCreated(`Participant ${participant.participant_code} registered in ${participant.study_code}.`);
    }
  }

  return (
    <>
      <PageHeading title="Participants" description="Code-only participant records you coordinate.">
        <button className="btn" onClick={openForm}><Plus />Register participant</button>
      </PageHeading>

      <div className="filters"><StudySelect value={studyFilter} onChange={setStudyFilter} /></div>

      {created && <div className="success-banner" role="status">{created}</div>}

      <LoadState query={participants}>
        <DataTable
          columns={['Participant', 'Study', 'Reviewer', 'Consent', 'Enrolled', '']}
          rows={participants.data}
          empty="No participants yet. Use “Register participant” to add one."
          renderRow={p => (
            <tr key={p.participant_id}>
              <td><Link to={`/coordinator/participants/${p.participant_id}`}>{p.participant_code}</Link></td>
              <td>{p.study_code}</td>
              <td>{p.reviewer_code}</td>
              <td><Badge value={p.consent_status} /></td>
              <td>{dateOnly(p.enrolled_at)}</td>
              <td>
                <Link to={`/coordinator/participants/${p.participant_id}`} aria-label={`Open ${p.participant_code}`}>
                  <ChevronRight size={16} />
                </Link>
              </td>
            </tr>
          )}
        />
      </LoadState>

      <div className="subtle-note"><ShieldCheck size={14} />Participants are identified by study code only. No personal details are stored.</div>

      <Modal open={open} onClose={() => setOpen(false)} title="Register participant"
        description={`The participant will be owned by you (${user.staff_code}).`}>
        <form onSubmit={submit}>
          <Field label="Study" name="study_id" error={save.error}>
            <select required value={form.study_id} onChange={e => set('study_id', e.target.value)}>
              <option value="">Select a study</option>
              {activeStudies.map(s => <option key={s.study_id} value={s.study_id}>{s.study_code} · {s.title}</option>)}
            </select>
          </Field>

          <Field label="Participant code">
            <div className="readonly-box">A participant code will be assigned automatically.</div>
          </Field>

          <Field label="Assigned reviewer" name="reviewer_code" error={save.error}>
            <select required value={form.reviewer_code} onChange={e => set('reviewer_code', e.target.value)} disabled={reviewers.isPending}>
              <option value="">{reviewers.isPending ? 'Loading reviewers…' : 'Select a reviewer'}</option>
              {reviewers.data?.map(r => <option key={r.staff_code} value={r.staff_code}>{r.display_label} · {r.staff_code}</option>)}
            </select>
          </Field>

          <Field label="Consent status" name="consent_status" error={save.error}>
            <select value={form.consent_status} onChange={e => set('consent_status', e.target.value)}>
              <option value="ACTIVE">Active</option>
              <option value="WITHDRAWN">Withdrawn</option>
            </select>
          </Field>

          <ErrorBanner error={save.error || reviewers.error} />
          <div className="form-actions">
            <button type="button" className="btn btn-outline" onClick={() => setOpen(false)}>Cancel</button>
            <SaveButton busy={save.busy} disabled={!reviewers.data?.length}>Register participant</SaveButton>
          </div>
        </form>
      </Modal>
    </>
  );
}